SELECT COUNT(DISTINCT bill_id) AS bills_with_atta, SUM(qty) AS units, ROUND(AVG(qty),3) AS avg_qty_per_bill, COUNT(*) AS lines
FROM store.pos_lines
WHERE sku_scanned='ATTA-WW-5KG' AND bill_ts >= DATE '2026-06-01' AND bill_ts < DATE '2026-07-01';

SELECT sku, COUNT(*) FILTER (WHERE units_sold=0) AS zero_days, SUM(units_sold) AS units, MIN(date) AS d1, MAX(date) AS d2
FROM store.daily_sales WHERE date >= DATE '2026-06-01' AND date < DATE '2026-07-01'
GROUP BY sku ORDER BY sku;

